test("person timeline scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-C", "3");
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "7.77", "note": "tpl"})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "33.33");
  await ui.setSetting(pg_uma, "fiscal-start-month", "7");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-01", "half-even")).toBe(true);
  await ui.setSetting(pg_uma, "review-sla", "1");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "1");
  await ui.setSetting(pg_uma, "score-log", "on");
  await ui.setSetting(pg_uma, "max-open", "3");
  await ui.setSetting(pg_uma, "pending-sla", "4");
  expect(await ui.addGrade(pg_uma, "D")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "contact": "ben@x", "tags": "b, a"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "terms": "20", "contact": "ADA@X"})).toBeNull();
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "terms": "3"})).toBeNull();
  expect(await ui.pasteClaims(pg_uma, "Ben,4.00,,a, b\nBen,3.33,2026-04-02,a, b\nBen,10.35,2026-03-28,")).toBe(3);
  const c_ben_0 = await ui.claimAt(pg_uma, p_ben, 0);
  const c_ben_1 = await ui.claimAt(pg_uma, p_ben, 1);
  const c_ben_2 = await ui.claimAt(pg_uma, p_ben, 2);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.bulkSettle(pg_wes, [c_ben_0, c_ben_1])).toEqual({ settled: 2, refused: 0 });
  expect(await ui.inlineGrade(pg_wes, p_ben, "A")).toBe(true);
  expect(await ui.remind(pg_wes, c_ben_2)).toBe(true);
  expect(await ui.periodAction(pg_wes, "P1", "close")).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  const c_ben_3 = ui.must(await ui.addClaimTwice(pg_vic, p_ben, {"amount": "10.25", "date": "2026-03-05"}));
  expect(await ui.claimCount(pg_vic, p_ben)).toBe(4);
  await ui.refresh(pg_vic);
  expect(await ui.setSettingDated(pg_vic, "floor", "3.00", "2026-03-15", "1.00")).toBe(true);
  expect(await ui.setRate(pg_vic, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.addLine(pg_vic, c_ben_3, {"label": "x", "qty": "3", "unit": "2.50"})).toBe(true);
  expect(await ui.exportCsv(pg_vic)).toBe("name,grade,retired-from,due-total\nBen,A,,5.00\n");
  expect(await ui.claimEditOpen(pg_vic, c_ben_3)).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.claimEditOpen(pg_uma, c_ben_3)).toBe(false);
  await ui.refresh(pg_vic);
  expect(await ui.claimEditSave(pg_vic, c_ben_3, {"amount": "20.00"})).toBe(false);
  const c_ben_4 = ui.must(await ui.addClaim(pg_vic, p_ben, {"amount": "7.77", "date": "2026-03-05", "tags": "a, B"}));

